<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\Reservation;use Illuminate\Http\Request;
class ReservationController extends Controller{public function index(Request $r){$q=Reservation::with('user:id,name')->orderBy('reserved_at');if($r->filled('from'))$q->where('reserved_at','>=',$r->input('from'));if($r->filled('to'))$q->where('reserved_at','<=',$r->input('to'));return response()->json($q->get());}public function store(Request $r){$d=$this->data($r);if(!empty($d['client_id'])&&($x=Reservation::where('client_id',$d['client_id'])->first()))return response()->json($x);$d['user_id']=$r->user()->id;return response()->json(Reservation::create($d)->load('user:id,name'),201);}public function update(Request $r,Reservation $reservation){$reservation->update($this->data($r,false));return response()->json($reservation->fresh()->load('user:id,name'));}public function destroy(Reservation $reservation){$reservation->delete();return response()->json(null,204);}private function data(Request $r,bool $creating=true){return $r->validate(['client_id'=>'nullable|uuid','contact_name'=>($creating?'required':'sometimes').'|string|max:255','phone'=>'nullable|string|max:50','social_media'=>'nullable|string|max:255','reserved_at'=>($creating?'required':'sometimes').'|date','party_size'=>'nullable|integer|min:1|max:500','status'=>'nullable|in:pending,confirmed,arrived,completed,cancelled,no_show','notes'=>'nullable|string|max:2000']);}}